s sH2C97c = ##class(User.MARC).getTagX(.h2,"C97c") ; typ operace pro h2
if '((sH1C97c="u") && (sH2C97c="u")) { 
  s sC97=##class(User.MARC).getTagX(.h1,"C97") }
else { 
  s sC97=##class(User.MARC).getTagX(.h2,"C97") 
} 

