      if subval'="" {
        if tagOpBef="X" { s sch1="CH1    "_$c(31)_"a"_date_$c(31)_"b"_user_$c(31)_"c"_s200eTxt_$c(31)_"e"_subval }  
        elseif tagOpAft="X" { s sch1="CH1    "_$c(31)_"a"_date_$c(31)_"b"_user_$c(31)_"c"_s200eTxt_$c(31)_"d"_subval }
      }*/
