; - ten umim ziskat jen z pouziteho formulare C99d
; - je na to index  zpz zapojeny ve fazete IPACu "Druh dokumentu", ale neni presny, napr. CavUnEpca 0577981 ma mit T1, ale zpz=T
; T1 - preklad z periodika
; T2 – preklad ze sborniku
; R1 – recenze z periodika
; R2 – recenze ze sborniku
; A1 – abstrakt z periodika
; A2 – abstrakt ze sborniku
; A3 - nepublikovana prednaska
if (fType="A1") || (fType="R1") || (fType="T1") {
